<script setup lang="ts">
import type {BirthdayPlan} from '../types';
import {money} from '../types';
defineProps<{plan:BirthdayPlan;busy?:boolean}>();
const emit=defineEmits<{manage:[id:string,action:string,version:number];suggest:[text:string]}>();
const time=(value:string)=>new Date(value).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false});
const state:Record<string,string>={succeeded:'已完成',waiting:'等待中',blocked:'已暂停',needs_input:'待补充',cancelled:'已取消',disabled:'未关注，不提醒'};
</script>
<template><article class="birthday-card" aria-label="生日计划">
  <header><div><span>生日安排 · 截至本次查询</span><h4>{{plan.contact_name}}的生日</h4></div><b>{{plan.status_label}}</b></header>
  <dl><div><dt>生日</dt><dd>{{plan.event_date}}</dd></div><div><dt>自动提醒</dt><dd>{{plan.notify_enabled ? time(plan.remind_at)+'（北京时间）' : '未特别关注，不自动提醒'}}</dd></div><div><dt>预算来源</dt><dd>{{plan.account_name}}</dd></div><div><dt>预算 / 已消费</dt><dd>¥{{money(plan.budget_minor)}} / ¥{{money(plan.spent_minor)}}</dd></div><div><dt>当前预留</dt><dd>¥{{money(plan.reserved_minor)}}</dd></div></dl>
  <details><summary>查看处理步骤</summary><ol><li v-for="step in plan.steps" :key="step.id"><span>{{step.title}}</span><small>{{state[step.status]||step.status}}</small></li></ol></details>
  <section v-if="plan.recommendation" class="birthday-recommendation"><p>{{plan.recommendation.message}}</p><div v-for="shop in plan.recommendation.menus" :key="shop.shop_id"><strong>{{shop.name}}</strong><small>配送费 ¥{{money(shop.delivery_minor)}} · {{shop.place.name}}</small><button v-for="item in shop.menu.filter(i=>i.available)" :key="item.id" :disabled="busy||plan.status!=='active'" @click="emit('suggest',`请使用${plan.contact_name} ${plan.event_date}的生日计划预算，从${plan.account_name}，在${shop.name}购买一份${item.name}，请重新报价并生成确认卡。`)"><span>{{item.name}}<small>打包费 ¥{{money(item.packing_minor)}} / 份</small></span><b>¥{{money(item.price_minor)}}</b></button></div></section>
  <p v-if="plan.order_id" class="birthday-note">模拟订单已创建，剩余预算已释放。订单编号：{{plan.order_id}}</p>
  <p v-else class="birthday-note">当前预留不代表已付款。选好商品后，仍需核对总价并验证支付密码及所需短信。</p>
  <footer v-if="['active','paused','needs_review'].includes(plan.status)"><button v-if="plan.status==='active'" :disabled="busy" @click="emit('manage',plan.id,'pause',plan.version)">暂停计划</button><button v-if="plan.status==='paused'" :disabled="busy" @click="emit('manage',plan.id,'resume',plan.version)">继续计划</button><button :disabled="busy" @click="emit('manage',plan.id,'cancel',plan.version)">取消计划</button><button :disabled="busy" @click="emit('suggest','查看最新的生日计划和预算状态')">查看最新状态</button></footer>
</article></template>
<style scoped>
.birthday-card{padding:17px;margin:16px 0;background:#faf9f2;border:1px solid #e6e6d8;border-radius:13px;min-width:0;color:#435745;font-size:12px;overflow-wrap:anywhere}.birthday-card header{display:flex;justify-content:space-between;align-items:center;gap:10px}.birthday-card header span{font-size:10px;color:#89917d}.birthday-card h4{margin:7px 0;font-size:17px;color:#365641}.birthday-card header>b{font-size:11px;font-weight:500;white-space:nowrap}.birthday-card dl{margin:15px 0}.birthday-card dl>div{display:flex;justify-content:space-between;gap:15px;margin:10px 0;line-height:1.7}.birthday-card dt{color:#8a947f;flex-shrink:0}.birthday-card dd{margin:0;text-align:right}.birthday-card summary{cursor:pointer;min-height:32px}.birthday-card ol{padding-left:18px}.birthday-card li{padding:7px 0;line-height:1.8}.birthday-card li small{float:right;color:#8d967f}.birthday-note{font-size:11px;line-height:1.9;color:#8a927f}.birthday-card footer{display:flex;flex-wrap:wrap;gap:8px}.birthday-card footer button{font:inherit;padding:8px 11px;background:white;border:1px solid #dce3d4;border-radius:7px;color:#557253;cursor:pointer}.birthday-recommendation{margin-top:12px;border-top:1px solid #e6e6d8}.birthday-recommendation p{line-height:1.8}.birthday-recommendation>div{padding:10px 0}.birthday-recommendation small{display:block;font-size:10px;color:#8c947e;margin:5px 0}.birthday-recommendation button{display:flex;align-items:center;justify-content:space-between;gap:12px;width:100%;text-align:left;margin:8px 0;padding:12px;background:white;border:1px solid #e3e7da;border-radius:8px;font:inherit;color:inherit;cursor:pointer}.birthday-recommendation button b{white-space:nowrap}.birthday-recommendation button:disabled{opacity:.55;cursor:default}@media(max-width:600px){.birthday-card{padding:13px}.birthday-card dl>div{font-size:12px}.birthday-card summary{min-height:44px}}
</style>
